-- Sum all revloss without any filtering
SELECT SUM(CAST(REPLACE(REPLACE(op.revloss, '$', ''), ',', '') AS numeric)) AS total_projected_revenue_loss
FROM operational_metrics op;

SELECT SUM(p.cap_mw * pm.degyrrate / 100.0) AS total_projected_revenue_loss
FROM plants p
JOIN panel_models pm ON p.modhook = pm.modkey;

SELECT SUM(pm.degyrrate) AS total_projected_revenue_loss
FROM plants p
JOIN panel_models pm ON p.modhook = pm.modkey;

SELECT SUM(pm.degyrrate) AS total_projected_revenue_loss
FROM plants p
JOIN panel_models pm ON p.modhook = pm.modkey;

SELECT SUM(p.cap_mw * pm.degyrrate / 1000.0) AS total_projected_revenue_loss
FROM plants p
JOIN panel_models pm ON p.modhook = pm.modkey;

SELECT SUM(p.cap_mw * pm.degyrrate) AS total_projected_revenue_loss
FROM plants p
JOIN panel_models pm ON p.modhook = pm.modkey;

SELECT SUM(DISTINCT p.cap_mw * pm.degyrrate) AS total_projected_revenue_loss
FROM plants p
JOIN panel_models pm ON p.modhook = pm.modkey;

SELECT SUM(CAST(REPLACE(REPLACE(op.revloss, '$', ''), ',', '') AS numeric)) AS total_projected_revenue_loss
FROM operational_metrics op
JOIN plant_record pr ON op.snapops = pr.snapkey;

SELECT SUM(DISTINCT p.cap_mw * pm.degyrrate / 100.0) AS total_projected_revenue_loss
